import itertools
opts={'A':('-','×'),'B':('÷','+'),'C':('-','+'),'D':('÷','×')}
toks=['29','×','145','+','5','-','640','÷','15']
def ev(t):
    e=''.join(t).replace('×','*').replace('÷','/').replace('-','-')
    return eval(e)
ok=[]
for k,(a,b) in opts.items():
