s='LM_O_NPMRO_KU_TI'
opts={'A':'RPMO','B':'PNOR','C':'NORP','D':'NOPR'}
def ok(f):
    t=list(s);
    for i,c in zip([i for i,x in enumerate(s) if x=='_'],f): t[i]=c
    g=[t[i:i+4] for i in range(0,16,4)]
    cols=list(zip(*g))
    def st(c):
        d=[ord(b)-ord(a) for a,b in zip(c,c[1:])]
        return len(set(d))==1
    return all(st(c) for c in cols)
r=[k for k,v in opts.items() if ok(v)]
assert r==['C']

